"""Repeatable, fail-closed qualification gate for the PyBoy backend."""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
from typing import Callable

import numpy as np

from pyboy_adapter import BackendCapabilityError, PyBoyAdvance


def visual_fingerprint(pixels: np.ndarray) -> dict[str, object]:
    """Return a compact fingerprint suitable for cross-process comparison."""

    if pixels.shape != (160, 240, 3):
        raise ValueError(f"unexpected framebuffer shape: {pixels.shape}")
    colors = np.unique(pixels.reshape(-1, 3), axis=0)
    return {
        "shape": list(pixels.shape),
        "sha256": hashlib.sha256(pixels.tobytes()).hexdigest(),
        "color_count": int(len(colors)),
    }


def qualify_repeated_boot(
    adapter_factory: Callable[[], PyBoyAdvance],
    *,
    frames: int,
    runs: int,
) -> dict[str, object]:
    """Require telemetry and an identical, visible frame across fresh runs."""

    if runs < 2:
        raise ValueError("runs must be at least 2")
    fingerprints: list[dict[str, object]] = []
    for run in range(runs):
        adapter = adapter_factory()
        adapter.require_capabilities("frames", "keys", "pixels", "read_telemetry")
        adapter.frame(frames)
        fingerprint = visual_fingerprint(adapter.pixels())
        if int(fingerprint["color_count"]) < 4:
            raise RuntimeError(
                f"run {run + 1} produced an unusably sparse framebuffer: {fingerprint}"
            )
        fingerprints.append(fingerprint)
    if len({item["sha256"] for item in fingerprints}) != 1:
        raise RuntimeError(f"fresh runs diverged: {fingerprints}")
    return {"runs": runs, "frames": frames, "fingerprint": fingerprints[0]}


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--rom", type=Path, required=True)
    parser.add_argument("--bios", type=Path, required=True)
    parser.add_argument("--frames", type=int, default=900)
    parser.add_argument("--runs", type=int, default=3)
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)

    def factory() -> PyBoyAdvance:
        return PyBoyAdvance(args.rom, args.bios, skip_bios=False, emulation_speed=0)

    try:
        result = qualify_repeated_boot(factory, frames=args.frames, runs=args.runs)
    except (BackendCapabilityError, OSError, RuntimeError, TypeError, ValueError) as exc:
        print(json.dumps({"qualified": False, "error": str(exc)}, sort_keys=True))
        return 1
    print(json.dumps({"qualified": True, **result}, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import numpy as np
import pytest

from pyboy_adapter import BackendCapabilityError
from qualification import qualify_repeated_boot, visual_fingerprint


class FakeAdapter:
    def __init__(self, pixels: np.ndarray, telemetry: bool = True) -> None:
        self._pixels = pixels
        self._telemetry = telemetry
        self.frame_count = 0

    def require_capabilities(self, *required: str) -> None:
        if "read_telemetry" in required and not self._telemetry:
            raise BackendCapabilityError("missing read-only memory telemetry")

    def frame(self, count: int = 1) -> None:
        self.frame_count += count

    def pixels(self) -> np.ndarray:
        return self._pixels.copy()


def visible_frame(seed: int) -> np.ndarray:
    pixels = np.zeros((160, 240, 3), dtype=np.uint8)
    pixels[:, :, 0] = seed
    pixels[0, 0] = [0, 1, 2]
    pixels[0, 1] = [3, 4, 5]
    pixels[0, 2] = [6, 7, 8]
    return pixels


def test_visual_fingerprint_is_stable_for_same_pixels() -> None:
    assert visual_fingerprint(visible_frame(10)) == visual_fingerprint(visible_frame(10))


def test_qualification_rejects_missing_telemetry() -> None:
    with pytest.raises(BackendCapabilityError, match="telemetry"):
        qualify_repeated_boot(
            lambda: FakeAdapter(visible_frame(10), telemetry=False), frames=3, runs=2
        )


def test_qualification_rejects_divergent_runs() -> None:
    seed = iter([10, 11])
    with pytest.raises(RuntimeError, match="diverged"):
        qualify_repeated_boot(
            lambda: FakeAdapter(visible_frame(next(seed))), frames=3, runs=2
        )


def test_qualification_accepts_identical_visible_runs() -> None:
    result = qualify_repeated_boot(
        lambda: FakeAdapter(visible_frame(10)), frames=3, runs=2
    )
    assert result["runs"] == 2
    assert result["frames"] == 3

/**
 * JSONL bridge for the existing jev-pokemon client.
 *
 * Run this file with tsx from the jev-pokemon checkout. The Python process
 * owns emulator input; this process only receives typed state/options and
 * returns a semantic option ID.
 */

import { createInterface } from 'node:readline';
import { pathToFileURL } from 'node:url';
import path from 'node:path';

const project = process.env.JEV_PROJECT;
if (!project) throw new Error('JEV_PROJECT must point to the jev-pokemon checkout');

const clientPath = pathToFileURL(path.join(project, 'src/jev/client.ts')).href;
const { Jev } = await import(clientPath);
const jev = new Jev({
  mode: 'gateway',
  logFile: process.env.JEV_LOG_FILE ?? 'logs/emerald-jev-calls.jsonl',
});

const input = createInterface({ input: process.stdin, crlfDelay: Infinity });
for await (const line of input) {
  if (!line.trim()) continue;
  try {
    const request = JSON.parse(line);
    const question = request.questions?.decision;
    if (question?.type !== 'choice' || !question.criteria) {
      throw new Error('request must contain a decision choice question');
    }
    const choice = await jev.choose(
      request.purpose ?? 'emerald',
      request.state,
      question.instructions,
      question.criteria,
    );
    process.stdout.write(JSON.stringify({ choice }) + '\n');
  } catch (error) {
    process.stderr.write(`[jev-sidecar] ${String(error)}\n`);
    process.stdout.write(JSON.stringify({ error: String(error) }) + '\n');
  }
}

